import * as React from 'react'

/**
 * Registers the service worker generated by vite-plugin-pwa.
 * Dynamic import keeps the virtual module out of the SSR bundle.
 */
export function PwaRegister() {
  React.useEffect(() => {
    // Skip on browsers without service worker support.
    if (!('serviceWorker' in navigator)) {
      return
    }

    let cancelled = false
    let updateTimer: ReturnType<typeof setInterval> | undefined

    import('virtual:pwa-register').then(({ registerSW }) => {
      if (cancelled) {
        return
      }

      registerSW({
        immediate: true,
        onRegisteredSW(_swUrl, registration) {
          // Check for updates every hour while the app stays open.
          if (registration) {
            updateTimer = setInterval(() => registration.update(), 60 * 60 * 1000)
          }
        },
      })
    })

    return () => {
      cancelled = true
      if (updateTimer) {
        clearInterval(updateTimer)
      }
    }
  }, [])

  return null
}
